<?php
$root=$argv[1];$stage=$argv[2];require $root.'/vendor/autoload.php';$app=require $root.'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema,Validator,Queue,Mail,Http};use Illuminate\Database\Schema\Blueprint;use App\Models\{Pdv,User,TagPurchase};
config(['database.default'=>'repasse_memory','database.connections.repasse_memory'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true],'cache.default'=>'array']);DB::setDefaultConnection('repasse_memory');if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:')throw new RuntimeException('Memory-only guard');Queue::fake();Mail::fake();Http::preventStrayRequests();
foreach(['app/Models/Pdv.php','app/Services/AdminService.php','app/Services/AdminPdvService.php','app/Http/Requests/StorePdvRequest.php','app/Http/Requests/UpdatePdvRequest.php','app/Http/Requests/Admin/StoreAdminUserRequest.php','app/Http/Requests/Admin/UpdateAdminUserRequest.php','app/Http/Resources/PdvResource.php'] as $file)require $stage.'/'.$file;
Schema::create('points_of_sale',function(Blueprint $t){$t->id();foreach(['name','cnpj','address','phone','responsible','map_link'] as $c)$t->string($c)->nullable();$t->boolean('active')->default(true);$t->softDeletes();$t->timestamps();});
(require $stage.'/database/migrations/2026_11_03_180000_add_commission_percentage_to_points_of_sale.php')->up();
Schema::create('users',function(Blueprint $t){$t->id();foreach(['name','email','password','cpf','birth_date','phone','gender','photo'] as $c)$t->string($c)->nullable();foreach(['type','pdv_id','user_id_admin_pdv','pdv_commission_type'] as $c)$t->integer($c)->nullable();$t->decimal('pdv_commission_value',8,2)->nullable();$t->softDeletes();$t->timestamps();});
// Use the live model table name, but only on the isolated in-memory connection.
Schema::create((new TagPurchase)->getTable(),function(Blueprint $t){$t->id();foreach(['user_id','vehicle_id','tag_id','qty','status'] as $c)$t->integer($c)->nullable();foreach(['mp_payment_status','mp_payment_id','payment_method'] as $c)$t->string($c)->nullable();foreach(['price','price_total','shipping_price'] as $c)$t->decimal($c,10,2)->nullable();$t->softDeletes();$t->timestamps();});
Schema::create('vehicles',function(Blueprint $t){$t->id();$t->integer('user_id')->nullable();foreach(['plate','name','color','year'] as $c)$t->string($c)->nullable();$t->softDeletes();$t->timestamps();});
$n=0;$ok=function($v,$label)use(&$n){if(!$v)throw new RuntimeException($label);$n++;};
foreach([new App\Http\Requests\StorePdvRequest,new App\Http\Requests\UpdatePdvRequest] as $r){$rules=['commission_percentage'=>$r->rules()['commission_percentage']];foreach([null,0,100,12.34,'8.5'] as $v)$ok(Validator::make(['commission_percentage'=>$v],$rules)->passes(),'accept valid rate');foreach([-1,100.01,'10.123','bad'] as $v)$ok(Validator::make(['commission_percentage'=>$v],$rules)->fails(),'reject invalid rate');}
$super=User::create(['name'=>'QA owner','email'=>'owner@example.test','password'=>'qa-test-password','type'=>1]);
$a=Pdv::create(['name'=>'QA point A','commission_percentage'=>10]);$b=Pdv::create(['name'=>'QA point B','commission_percentage'=>20]);$empty=Pdv::create(['name'=>'QA point empty']);
$staff1=User::create(['name'=>'QA A1','type'=>2,'pdv_id'=>$a->id,'pdv_commission_type'=>1,'pdv_commission_value'=>99]);$staff2=User::create(['name'=>'QA A2','type'=>2,'pdv_id'=>$a->id,'pdv_commission_type'=>2,'pdv_commission_value'=>90]);$staff3=User::create(['name'=>'QA B','type'=>2,'pdv_id'=>$b->id]);
$c1=User::create(['name'=>'QA customer1','type'=>3,'user_id_admin_pdv'=>$staff1->id]);$c2=User::create(['name'=>'QA customer2','type'=>3,'user_id_admin_pdv'=>$staff2->id]);$c3=User::create(['name'=>'QA customer3','type'=>3,'user_id_admin_pdv'=>$staff3->id]);
foreach([[$c1,29.90,'approved'],[$c2,59.80,'approved'],[$c1,500,'pending'],[$c1,400,'refunded'],[$c3,100,'approved']] as $i=>[$u,$amount,$status])DB::table((new TagPurchase)->getTable())->insert(['user_id'=>$u->id,'qty'=>1,'price_total'=>$amount,'mp_payment_status'=>$status,'mp_payment_id'=>'qa-'.$i,'created_at'=>now(),'updated_at'=>now()]);
$service=new App\Services\AdminService;$rows=$service->pdvCommissions(null,null,null,null,100)->getCollection()->keyBy('pdv_id');
$ok($rows->count()===3,'one row for each point');$ok($rows[$a->id]['staff_count']===2,'both staff grouped');$ok($rows[$a->id]['total_sales_qty']===2,'no duplicate sales');$ok(abs($rows[$a->id]['total_sales_amount']-89.70)<.001,'only approved sales');$ok($rows[$a->id]['commission_amount']===8.97,'PDV percentage overrides legacy personal rates');$ok($rows[$b->id]['commission_amount']===20.0,'other point remains separate');$ok($rows[$empty->id]['commission_value']===null&&$rows[$empty->id]['commission_amount']===0.0,'blank rate is not invented');
$ok($service->pdvCommissions(null,null,$staff2->id,null,100)->total()===1,'admin filter maps to the point');$ok($service->pdvCommissions(null,null,null,'QA point A',100)->total()===1,'search by point');$ok($service->pdvCommissions('2035-01-01',null,null,null,100)->getCollection()->sum('commission_amount')===0.0,'open date boundary honored');
foreach([$staff1,$staff2] as $staff){$result=(new App\Services\AdminPdvService)->dashboard($staff->fresh(),date('Y-m-d'),date('Y-m-d'));$expected=$staff->id===$staff1->id?2.99:5.98;$ok(abs($result['totals']['commission_amount']-$expected)<.001,'staff dashboard uses point rate with own sales only');}
$a->update(['commission_percentage'=>15]);$rows=$service->pdvCommissions(null,null,null,null,100)->getCollection()->keyBy('pdv_id');$ok($rows[$a->id]['commission_amount']===13.46,'one PDV edit updates combined report');
$ok($a->commissionAmount(29.90)===4.49,'round money to cents');$ok((new Pdv(['commission_percentage'=>0]))->commissionAmount(29.90)===0.0,'zero rate');$ok((new Pdv(['commission_percentage'=>100]))->commissionAmount(29.90)===29.9,'full rate');
foreach([new App\Http\Requests\Admin\StoreAdminUserRequest,new App\Http\Requests\Admin\UpdateAdminUserRequest] as $r){$rules=$r->rules();$v=Validator::make(['pdv_commission_type'=>2,'pdv_commission_value'=>99],['pdv_commission_type'=>$rules['pdv_commission_type'],'pdv_commission_value'=>$rules['pdv_commission_value']]);$ok($v->validated()===[],'cached user fields are excluded');}
$created=$service->createUser(['name'=>'QA new admin','email'=>'new@example.test','password'=>'qa-test-12345','type'=>2,'pdv_id'=>$a->id,'pdv_commission_type'=>2,'pdv_commission_value'=>99],$super);$ok($created->pdv_commission_value===null,'service does not store personal rate');$service->updateUser($staff1->id,['pdv_commission_value'=>80]);$ok((float)$staff1->fresh()->pdv_commission_value===99.0,'service ignores personal rate updates');
$request=Illuminate\Http\Request::create('/qa');$request->setUserResolver(fn()=>$super);$ok((new App\Http\Resources\PdvResource($a))->resolve($request)['commission_percentage']==='15.00','owner can read PDV rate');$request->setUserResolver(fn()=>null);$ok(!array_key_exists('commission_percentage',(new App\Http\Resources\PdvResource($a))->resolve($request)),'public point listing does not leak commission');
echo 'PASS '.$n.' isolated commission checks; SQLite memory only, no payment, mail, or production writes.'.PHP_EOL;
